/**
 * openclaw-turn-plugin.ts — OpenClaw's native per-turn hook for the
 * brain-first rule: a hook-only OpenClaw plugin whose `before_prompt_build`
 * handler returns the rule as `prependContext`, so it reaches the model next
 * to each user turn (without its reply sentence on `internal_system` turns).
 * The workspace AGENTS.md block reaches the system prompt only, and bots read
 * it as identity, not as an instruction to call a tool.
 *
 * The plugin is self-contained (the rule text is written into its code; it
 * reads nothing and calls nothing) and lives in <OpenClaw state dir>/gbrain/.
 * Setup installs it with OpenClaw's own CLI, the supported path: a linked
 * install with capability consent, enabled, and
 * `plugins.entries.gbrain-turn-rule.hooks.allowConversationAccess`, which
 * OpenClaw requires of a non-bundled plugin's `before_prompt_build`. With no
 * `openclaw` on PATH, setup writes the plugin and prints those commands.
 */
import { existsSync, mkdirSync, readdirSync, readFileSync, rmdirSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { atomicWriteTextFile } from '../bootstrap/atomic-write.ts';
import { bunSpawnSync } from '../spawn.ts';
import { openclawConfigPath, openclawStateDir, parseJson5ish, renderBrainFirstTurnRule, type BrainFirstAccess } from './brain-first.ts';

export const OPENCLAW_TURN_PLUGIN_ID = 'gbrain-turn-rule';

export interface OpenclawTurnPluginOutcome { action: 'write' | 'keep' | 'print' | 'remove' | 'skip'; path: string; detail: string; commands?: string[]; unchanged?: true }

/** Whether OpenClaw's config already loads the plugin at dir, enables it, lets its plugin policy (plugins.enabled, allow, deny) load it and allows it conversation access (so no CLI call is needed). */
export function openclawPluginRegistered(id: string, dir: string): boolean {
  try {
    const cfg = parseJson5ish(readFileSync(openclawConfigPath(), 'utf8')) as { plugins?: { enabled?: unknown; allow?: unknown; deny?: unknown; load?: { paths?: unknown }; entries?: Record<string, { enabled?: unknown; hooks?: { allowConversationAccess?: unknown } }> } } | undefined;
    const plugins = cfg?.plugins;
    const entry = plugins?.entries?.[id];
    const paths = Array.isArray(plugins?.load?.paths) ? plugins!.load!.paths as unknown[] : [];
    const allowed = plugins?.enabled !== false && !(Array.isArray(plugins?.deny) && plugins!.deny.includes(id)) && !(Array.isArray(plugins?.allow) && plugins!.allow.length > 0 && !plugins!.allow.includes(id));
    return allowed && !!entry && entry.enabled !== false && entry.hooks?.allowConversationAccess === true && paths.includes(dir);
  } catch { return false; }
}

export function openclawTurnPluginDir(): string {
  return join(openclawStateDir(), 'gbrain', OPENCLAW_TURN_PLUGIN_ID);
}

const DESCRIPTION = 'Puts the GBrain brain-first rule next to every user turn (managed by gbrain setup openclaw).';

export function openclawTurnPluginFiles(access: BrainFirstAccess): Record<string, string> {
  const rule = renderBrainFirstTurnRule(access, 'openclaw');
  return {
    'package.json': `${JSON.stringify({ name: OPENCLAW_TURN_PLUGIN_ID, version: '1.0.0', private: true, type: 'module', openclaw: { extensions: ['./index.js'] }, gbrain: { access } }, null, 2)}\n`,
    'openclaw.plugin.json': `${JSON.stringify({ id: OPENCLAW_TURN_PLUGIN_ID, name: 'GBrain turn rule', description: DESCRIPTION, configSchema: { type: 'object', additionalProperties: false } }, null, 2)}\n`,
    'index.js': [
      '// Managed by gbrain setup openclaw; a re-run rewrites this file. Remove: gbrain setup openclaw --remove',
      `const RULE = ${JSON.stringify(rule)};`,
      `const INTERNAL_RULE = ${JSON.stringify(renderBrainFirstTurnRule(access, 'openclaw', { reply: false }))};`,
      'export default {',
      `  id: ${JSON.stringify(OPENCLAW_TURN_PLUGIN_ID)},`,
      "  name: 'GBrain turn rule',",
      `  description: ${JSON.stringify(DESCRIPTION)},`,
      '  register(api) {',
      "    api.on('before_prompt_build', (_event, ctx) => ({ prependContext: ctx?.inputProvenance?.kind === 'internal_system' ? INTERNAL_RULE : RULE }));",
      '  },',
      '};',
      '',
    ].join('\n'),
  };
}

type Run = (argv: string[]) => { ok: boolean; output: string };

/** One openclaw CLI call; a call killed at its timeout ends its output with "timed out after N s", so the failure line names the stall instead of the last thing it printed. */
export function runOpenclawCli(argv: string[], timeout = 120_000): { ok: boolean; output: string; stdout: string } {
  const r = bunSpawnSync(argv, { stdin: 'ignore', stdout: 'pipe', stderr: 'pipe', env: process.env, timeout });
  const output = `${r.stdout.toString()}${r.stderr.toString()}`.trim();
  return { ok: r.exitCode === 0, output: r.exitedDueToTimeout ? `${output}
timed out after ${timeout / 1000} s`.trim() : output, stdout: r.stdout.toString() };
}

function findOpenclaw(): string | null {
  try { return Bun.which('openclaw', { PATH: process.env.PATH ?? '' }); } catch { return null; }
}

const installArgv = (bin: string, dir: string): string[][] => [
  [bin, 'plugins', 'install', '--link', dir, '--force', '--accept-capabilities'],
  [bin, 'plugins', 'enable', OPENCLAW_TURN_PLUGIN_ID],
  [bin, 'config', 'set', `plugins.entries.${OPENCLAW_TURN_PLUGIN_ID}.hooks.allowConversationAccess`, 'true'],
];

const shown = (argv: string[]) => argv.map((a) => (/^[\w./:=@-]+$/.test(a) ? a : `'${a.replace(/'/g, `'\\''`)}'`)).join(' ');

/**
 * What an installed plugin was written for: the access its package.json records, else (an older gbrain recorded
 * none) the server or launcher its RULE literal names. undefined with no plugin, null when neither can be read.
 */
function installedAccess(dir: string): { access: BrainFirstAccess; recorded: boolean } | null | undefined {
  if (!existsSync(join(dir, 'index.js'))) return undefined;
  try {
    const recorded = (JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8')) as { gbrain?: { access?: BrainFirstAccess } }).gbrain?.access;
    if (recorded) return { access: recorded, recorded: true };
    const literal = /^const RULE = (".*");$/m.exec(readFileSync(join(dir, 'index.js'), 'utf8'))?.[1];
    const rule = literal ? JSON.parse(literal) as string : '';
    const server = /on the `([^`]+)` MCP server/.exec(rule)?.[1];
    const launcher = /check GBrain first \(`(.+?) search "<names>"`/.exec(rule)?.[1];
    return server ? { access: { kind: 'mcp', server }, recorded: false } : launcher ? { access: { kind: 'cli', launcher }, recorded: false } : null;
  } catch { return null; }
}

const named = (a: BrainFirstAccess) => (a.kind === 'mcp' ? `the \`${a.server}\` MCP server` : `\`${a.launcher}\``);

/**
 * Write the plugin and install it with OpenClaw's CLI (accepted decision). Never throws. Every agent on the gateway gets
 * the plugin's rule, so a `workspace`-scoped run leaves an installed plugin whose rule would name another server (or
 * one it cannot read) and prints, unverified, the command that changes it for every agent.
 */
export function syncOpenclawTurnPlugin(opts: { access: BrainFirstAccess; dryRun: boolean; workspace?: string; openclawBin?: string | null; run?: Run }): OpenclawTurnPluginOutcome {
  const dir = openclawTurnPluginDir();
  const installed = opts.workspace ? installedAccess(dir) : undefined;
  const same = installed && (installed.recorded
    ? renderBrainFirstTurnRule(installed.access, 'openclaw') === renderBrainFirstTurnRule(opts.access, 'openclaw')
    : named(installed.access) === named(opts.access));
  if (installed !== undefined && !same) {
    return { action: 'print', path: dir, detail: `${dir} left as it is: every agent on this OpenClaw gateway gets its rule, which ${installed ? `names ${named(installed.access)}` : 'gbrain cannot read'}, so a --workspace run does not rewrite it. To change it for every agent, run this, then this setup again`, commands: [`gbrain setup openclaw --remove --workspace ${opts.workspace}`] };
  }
  const files = openclawTurnPluginFiles(opts.access);
  const bin = opts.openclawBin !== undefined ? opts.openclawBin : findOpenclaw();
  const commands = installArgv(bin ?? 'openclaw', dir);
  const changed = Object.entries(files).some(([name, text]) => {
    try { return readFileSync(join(dir, name), 'utf8') !== text; } catch { return true; }
  });
  if (opts.dryRun) return { action: changed ? 'write' : 'keep', path: dir, detail: `per-turn rule plugin ${OPENCLAW_TURN_PLUGIN_ID} (before_prompt_build) at ${dir}${bin ? ', installed with the openclaw CLI' : ''}` };
  try {
    if (changed) {
      mkdirSync(dir, { recursive: true });
      for (const [name, text] of Object.entries(files)) atomicWriteTextFile(join(dir, name), text, { freshMode: 0o644 });
    }
  } catch (e) {
    return { action: 'print', path: dir, detail: `the plugin could not be written to ${dir} (${(e as Error).message})` };
  }
  if (!changed && openclawPluginRegistered(OPENCLAW_TURN_PLUGIN_ID, dir)) return { action: 'keep', path: dir, detail: `per-turn rule plugin ${OPENCLAW_TURN_PLUGIN_ID} (before_prompt_build) at ${dir}, already installed, enabled and allowed in OpenClaw, so no openclaw command ran`, unchanged: true };
  if (!bin) return { action: 'print', path: dir, detail: `plugin written to ${dir}; no openclaw on PATH, so run these on the OpenClaw host, then restart the gateway`, commands: commands.map(shown) };
  const run = opts.run ?? runOpenclawCli;
  for (const [i, argv] of commands.entries()) {
    const r = run(argv);
    if (!r.ok) return { action: 'print', path: dir, detail: `\`${shown(argv)}\` failed (${r.output.split('\n').at(-1) ?? 'no output'}); run the rest yourself`, commands: commands.slice(i).map(shown) };
  }
  return { action: changed ? 'write' : 'keep', path: dir, detail: `per-turn rule plugin ${OPENCLAW_TURN_PLUGIN_ID} (before_prompt_build) at ${dir}, installed and enabled; restart the gateway if it is running` };
}

/**
 * Uninstall the plugin, then delete its directory (decline or --remove). Never throws. The directory stays
 * until the uninstall succeeds: `install --link` put it in plugins.load.paths, and OpenClaw refuses a config
 * whose load path is missing.
 */
export function removeOpenclawTurnPlugin(opts: { dryRun: boolean; workspace?: string; openclawBin?: string | null; run?: Run }): OpenclawTurnPluginOutcome {
  const dir = openclawTurnPluginDir();
  if (!existsSync(dir)) return { action: 'skip', path: dir, detail: `no per-turn rule plugin at ${dir}` };
  if (opts.workspace) return { action: 'skip', path: dir, detail: `${dir} left in place: every agent on this OpenClaw gateway gets its rule, so opting out one workspace does not remove it. Remove it for every agent with gbrain setup openclaw --remove --workspace ${opts.workspace}` };
  if (opts.dryRun) return { action: 'remove', path: dir, detail: `per-turn rule plugin ${OPENCLAW_TURN_PLUGIN_ID} at ${dir}` };
  const bin = opts.openclawBin !== undefined ? opts.openclawBin : findOpenclaw();
  const uninstall = [bin ?? 'openclaw', 'plugins', 'uninstall', OPENCLAW_TURN_PLUGIN_ID, '--force'];
  const r = bin ? (opts.run ?? runOpenclawCli)(uninstall) : { ok: false, output: 'no openclaw on PATH' };
  if (!r.ok) return { action: 'print', path: dir, detail: `${dir} left in place (OpenClaw still loads it); ${r.output.split('\n').at(-1)}, so run this on the OpenClaw host, then delete ${dir}`, commands: [shown(uninstall)] };
  try {
    rmSync(dir, { recursive: true, force: true });
    if (readdirSync(dirname(dir)).length === 0) rmdirSync(dirname(dir));
  } catch { /* uninstalled; a leftover directory is no longer loaded */ }
  return { action: 'remove', path: dir, detail: `per-turn rule plugin ${OPENCLAW_TURN_PLUGIN_ID} uninstalled and ${dir} removed` };
}
 * not write (opencode, openclaw, hermes, cursor): manage the brain-first
 * block and nothing else. A client with no instruction file gbrain can write
 * (Claude Desktop, ChatGPT, …) gets the block printed to paste.
 */
async function runInstructionsOnly(flags: SetupFlags, out: Out): Promise<number> {
  const harness = flags.harness!;
  const adapter = HARNESS_ADAPTERS.find((a) => a.id === harness)!;
  const envSurface = process.env.GBRAIN_SURFACE;
  const surface = flags.surface ?? (isRegistrationSurface(envSurface) ? envSurface : undefined);
  const access: BrainFirstAccess = { kind: 'mcp', server: flags.name, ...(surface ? { surface } : {}), ...(flags.serves === 'several' && servesBound(flags) ? { serves: 'several' as const } : {}) };
  const hermesMcp = harness === 'hermes' && !flags.instructionsOnly
    ? hermesMcpStep({ hermesHome: dirname((brainFirstTarget('hermes', {}) as { path: string }).path), name: flags.name, surface, gbrainBin: flags.gbrainBin ?? resolveGbrainBin(), remove: flags.remove, dryRun: flags.dryRun })
    : null;
  const mcp = hermesMcp ? { setup: hermesMcp.action, docs: adapter.guide, detail: hermesMcp.detail, ...(hermesMcp.command ? { command: hermesMcp.command } : {}) }
    : { setup: flags.instructionsOnly ? 'unchanged' as const : 'manual' as const, docs: adapter.guide };
  const exposure = flags.remove || !BOT_HARNESSES.includes(harness) ? null
    : sharedTokenNotice({ kind: 'stdio', harness }, { harness, serves: exposureServesVia(flags.gbrainBin ?? resolveGbrainBin()) });
  const notices = renderedExposure(exposure);
  if (!isBrainFirstHarness(harness)) {
    const pasted: BrainFirstAccess = adapter.connection === 'thin-cli' ? { kind: 'cli', launcher: flags.gbrainBin ?? 'gbrain' } : access;
    const snippet = renderBrainFirstSnippet(harness, pasted, 'delete this block');
    if (out.json) {
      await writeJsonDocument(`${JSON.stringify({ harness, dry_run: flags.dryRun, remove: flags.remove, instructions_only: true,
        instructions: { action: 'print', snippet, where: `${adapter.label}'s custom or system instructions` }, mcp, notices }, null, 2)}\n`, (t) => process.stdout.write(t));
      return 0;
    }
    writeExposureNotice(exposure);
    console.log(`${adapter.label} has no instruction file gbrain can write. Paste this block into its custom or system instructions (keep the markers so a later paste replaces it):\n`);
    console.log(snippet);
    console.log(adapter.connection === 'thin-cli'
      ? `The thin-CLI install in ${adapter.guide} already puts this block at the top of GBRAIN-INSTRUCTIONS.md; pass --gbrain-bin <absolute launcher> to print it with that launcher.`
      : `Connect its MCP server with ${adapter.guide}.`);
    return 0;
  }
  const projectDir = harness === 'cursor' || (harness === 'claude-code' && flags.scope === 'project') ? realpathSync(process.cwd()) : undefined;
  const where = { scope: harness === 'claude-code' ? flags.scope ?? 'user' : undefined, projectDir };
  const target = brainFirstTarget(harness, { ...where, workspace: flags.workspace });
  if ('error' in target) {
    return refuse(opError('invalid_params', target.error, 'Pass --workspace <absolute dir> for the agent whose AGENTS.md should carry the block.'), out);
  }
  let instructions: BrainFirstOutcome | null;
  let skills: SkillsBlockOutcome | null;
  if (flags.remove) {
    instructions = removeBrainFirstFor(harness, where, flags);
    skills = removeSkillsFor(harness, where, flags);
  } else {
    say(out, `Target (${adapter.label}): ${target.path} (${target.role})`);
    const decision = resolveBrainFirstDecision(flags.instructions, priorBrainFirst(harness, target.path));
    instructions = syncBrainFirst({ target, access, decision, writer: `gbrain setup ${harness}`, dryRun: flags.dryRun });
    skills = skillsFor(harness, flags, flags.gbrainBin ?? indexLauncher() ?? 'gbrain', where, instructions);
  }
  const off = flags.remove || instructions?.decision.value === 'declined';
  const rerun = ['gbrain', 'setup', harness, '--instructions-only', ...(flags.name !== 'gbrain' ? ['--name', flags.name] : []), ...(flags.workspace ? ['--workspace', flags.workspace] : []), ...(projectDir && harness === 'claude-code' ? ['--scope', 'project'] : [])];
  // The hook carries the block's rule, so it follows the block: none while no block could be placed (Hermes without a SOUL.md).
  const placed = instructions?.action === 'write' || instructions?.action === 'keep';
  const turnHook = !off && !placed ? null : harness === 'hermes'
    ? (off ? removeHermesTurnHook({ hermesHome: dirname(target.path), dryRun: flags.dryRun }) : syncHermesTurnHook({ hermesHome: dirname(target.path), access, dryRun: flags.dryRun }))
    : harness === 'openclaw'
      ? (off ? removeOpenclawTurnPlugin({ dryRun: flags.dryRun, workspace: flags.remove ? undefined : flags.workspace }) : syncOpenclawTurnPlugin({ access, dryRun: flags.dryRun, workspace: flags.workspace }))
      : isTurnRuleHarness(harness) ? turnRuleHookFor(harness, off, flags, projectDir, rerun.join(' ')) : null;
  // Loud failure: an accepted install whose per-turn hook does not load exits non-zero and names the harness's own check.
  // A 'print' outcome installed nothing and already names the step that does, so it is reported, not verified.
  const check = !off && !flags.dryRun && instructions?.decision.value === 'accepted' && !flags.noHooks && process.env.GBRAIN_HOOKS !== '0' && turnHook && turnHook.action !== 'print' && turnHook.action !== 'remove' && !('unchanged' in turnHook && turnHook.unchanged) ? verifyTurnHook(harness, { projectDir }) : null;
  const resolver = harness === 'claude-code' || harness === 'codex' || harness === 'hermes' ? await resolverFor(harness, flags, flags.gbrainBin ?? resolveGbrainBin() ?? '') : null;
  const skillPlugin = harness === 'openclaw' ? await openclawSkillFor(flags) : null;
  const cursorPins = harness === 'cursor' && projectDir ? await cursorPinsFor(flags, projectDir) : null;
  const code = instructions?.action === 'preserve' || hermesMcp?.action === 'error' || skillsFailed(skills) || (check && !check.ok) || resolver?.error || cursorPins?.error ? 1 : 0;
  if (out.json) {
    await writeJsonDocument(`${JSON.stringify({ harness, dry_run: flags.dryRun, remove: flags.remove, instructions_only: true, instructions, ...(turnHook ? { turn_hook: turnHook } : {}), ...(check ? { turn_hook_check: check } : {}), skills, ...(resolver ? { skill_resolver: resolver } : {}), ...(skillPlugin ? { skill_resolver: skillPlugin } : {}), ...(cursorPins ? { skill_pins: cursorPins } : {}), mcp, notices }, null, 2)}\n`, (t) => process.stdout.write(t));
    return skillPlugin?.error ? exitCodeForCode(skillPlugin.error.code) : code;
  }
  writeExposureNotice(exposure);
  if (instructions) say(out, flags.remove ? describeBrainFirstOutcome(instructions, flags.dryRun) : describeInstructions(instructions, flags.dryRun));
  if (turnHook) say(out, `  ${(flags.dryRun && (turnHook.action === 'write' || turnHook.action === 'remove') ? `would ${turnHook.action}` : turnHook.action).padEnd(8)} ${'turn hook'.padEnd(7)} ${turnHook.detail}${'snippet' in turnHook && turnHook.snippet ? `:\n${turnHook.snippet.replace(/^/gm, '    ')}` : ''}${'commands' in turnHook && turnHook.commands ? `:\n${turnHook.commands.map((c) => `    ${c}`).join('\n')}` : ''}${'next' in turnHook && turnHook.next ? `; wire it with: ${turnHook.next}` : ''}`);
  else if (!off && placed) say(out, `  note     ${'turn hook'.padEnd(7)} ${adapter.label} has no per-turn hook gbrain can install; the rule reaches it through ${target.path} only.`);
  if (skills && skillsOutcomeShown(skills)) say(out, describeSkillsBlockOutcome(skills, flags.dryRun));
  if (resolver) for (const line of describeResolverSetup(resolver, flags.dryRun)) say(out, line);
  if (skillPlugin) for (const line of describeOpenclawSkill(skillPlugin, flags.dryRun)) say(out, line);
  if (harness === 'openclaw' && turnHook && !off) say(out, `  note     ${'route'.padEnd(7)} the per-turn rule is OpenClaw's primary route to the brain. Skills from \`gbrain skillpack scaffold --harness openclaw\` are an optional fallback: agents seldom open a listed skill on their own.`);
  if (cursorPins) for (const line of describeCursorPins(cursorPins, flags.dryRun)) say(out, line);
  if (check?.ok) say(out, `  verify   ${'turn hook'.padEnd(7)} ${check.message}`);
  if (mcp.setup === 'manual' && !flags.remove) say(out, `MCP: setup does not register ${adapter.label}'s MCP server. Follow ${adapter.guide} (one command), then start a new session.`);
  if (hermesMcp) say(out, `  ${hermesMcp.action.padEnd(8)} ${'MCP'.padEnd(7)} ${hermesMcp.detail}${hermesMcp.command && hermesMcp.action !== 'write' ? `:\n    ${hermesMcp.command}` : ''}`);
  if (!flags.remove && instructions?.decision.value === 'accepted') say(out, 'Next: start a new session; the harness reads its instruction file at session start.');
  if (resolver?.error) return refuse(resolverRefusal(resolver), out);
  if (skillPlugin?.error) return refuse(openclawSkillRefusal(skillPlugin), out);
  if (cursorPins?.error) {
    const e = cursorPins.error;
    return refuse(opError(e.code, e.message, 'Fix the cause named above, then preview with gbrain setup cursor --skill-loading resolve --dry-run from the project directory.', {
      docs: `docs/guides/skill-resolver.md#${e.code}`,
      fix: { argv: ['gbrain', 'setup', 'cursor', '--skill-loading', 'resolve', '--dry-run'], consent: [], actor: 'agent', requires_exclusive: false, why: 'Previews every write the Cursor pinned-skills setup would make in this project; changes nothing.' } }), out);
  }
  if (check && !check.ok) return refuse(turnHookNotLoaded(harness, check, rerun), out);
  return code;
}

/**

{
  "reply": "[openclaw] running: config.set\nUpdated mcp.servers.gbrain. Change will apply without restarting the gateway.\n[openclaw] done: config.set"
}

