import {Client} from '/harness-state/.bun/install/global/node_modules/@modelcontextprotocol/sdk/dist/esm/client/index.js';
import {StdioClientTransport} from '/harness-state/.bun/install/global/node_modules/@modelcontextprotocol/sdk/dist/esm/client/stdio.js';
import {readFileSync} from 'node:fs';
import {createRequire} from 'node:module';
const req=createRequire(import.meta.url), cfg=req('/opt/harness/lib/node_modules/openclaw/node_modules/json5').parse(readFileSync(process.env.OPENCLAW_CONFIG_PATH,'utf8'));
const {command,args}=cfg.mcp.servers.gbrain;
const entity='gbrain-mcp-install-check', fact='GBrain MCP installation test marker: silverkettle760.';
let id;
async function using(fn){const c=new Client({name:'gbrain-install-check',version:'1.0.0'}); const t=new StdioClientTransport({command,args,stderr:'inherit'}); try{await c.connect(t);return await fn(c);}finally{await c.close();}}
async function call(c,name,args){const r=await c.callTool({name,arguments:args}); if(r.isError)throw new Error(JSON.stringify(r));return r.structuredContent??JSON.parse(r.content.find(x=>x.type==='text').text);}
await using(async c=>{const {tools}=await c.listTools(); for(const n of ['remember','recall','forget'])if(!tools.some(t=>t.name===n))throw new Error(`Missing ${n}`);const r=await call(c,'remember',{fact,entity,provenance:'install-check',ttl:'24h',content_origin:'inferred'});if(r.status!=='inserted'||!r.id)throw new Error(JSON.stringify(r));id=r.id;console.log(`MCP remember: ${r.status}, id=${id}`);});
await using(async c=>{const r=await call(c,'recall',{entity});if(!r.facts?.some(x=>x.fact===fact&&String(x.id)===String(id)))throw new Error(JSON.stringify(r));console.log(`MCP recall (independent server process): matched fact ${id}`);const f=await call(c,'forget',{fact_id:Number(id)});const afterward=await call(c,'recall',{entity});if(afterward.facts?.some(x=>String(x.id)===String(id)))throw new Error(JSON.stringify({f,afterward}));console.log(`MCP forget: fact ${id} no longer active`);});
EOF
node "$d/mcp-test.mjs"

